.darma-loader-tw-button-spinner { display: inline-flex; align-items: center; gap: calc(var(--loader-size, 160px) * .07); width: var(--loader-size, 160px); padding: calc(var(--loader-size, 160px) * .07) calc(var(--loader-size, 160px) * .1); border-radius: 9999px; background: var(--loader-color, #4f46e5); box-sizing: border-box; }
.darma-loader-tw-button-spinner .darma-loader-tw-button-spinner__spinner { flex: none; width: calc(var(--loader-size, 160px) * .14); height: calc(var(--loader-size, 160px) * .14); border-radius: 9999px; border: calc(var(--loader-size, 160px) * .028) solid rgba(255, 255, 255, .35); border-top-color: #ffffff; animation: darma-loader-tw-button-spinner-twSpin var(--loader-speed, 1s) linear infinite; }
.darma-loader-tw-button-spinner .darma-loader-tw-button-spinner__label { flex: 1; height: calc(var(--loader-size, 160px) * .08); border-radius: 9999px; background: rgba(255, 255, 255, .7); }
@keyframes darma-loader-tw-button-spinner-twSpin { to { transform: rotate(360deg); } }

